/*
 * A RUNBOOK'S WEBHOOK URL: what another tool calls to start the runbook.
 *
 *   POST https://<host>/runbook/webhook/<runbook id>/<secret key>
 *
 * The secret key is the credential: 32 random bytes, generated by the server
 * when the webhook is first turned on (RunbookService), compared in constant
 * time on every call, never readable through the API's runbook reads, and
 * shown only to people who may both change the runbook's triggers and run it
 * (RunbookTriggerAccess). Resetting it gives the runbook a new URL and the
 * old one stops working at once.
 *
 * Only POST starts a run. A GET is answered with how to call it and starts
 * nothing: a chat app that previews a pasted link sends a GET, and must not
 * run the runbook.
 *
 * The request's JSON body becomes the run's inputs (Types/Runbook/
 * RunbookInputs) - data the steps read, never text pasted into a script.
 *
 * Kept free of server and React code, so the server's route, the Triggers
 * page and the tests read the same constants and the same sentences.
 */

// Relative to the runbook service, which the dashboard knows as RUNBOOK_URL.
export const RUNBOOK_WEBHOOK_PATH: string = "/webhook";

// The route the server registers, relative to the runbook service.
export const RUNBOOK_WEBHOOK_ROUTE: string = `${RUNBOOK_WEBHOOK_PATH}/:runbookId/:secretKey`;

/*
 * Where the Triggers page reads the key and resets it, relative to the
 * runbook service. Not under /webhook: those addresses are the public URL's.
 */
export const RUNBOOK_WEBHOOK_SECRET_ROUTE: string =
  "/webhook-secret/:runbookId";
export const RUNBOOK_WEBHOOK_SECRET_RESET_ROUTE: string = `${RUNBOOK_WEBHOOK_SECRET_ROUTE}/reset`;

// 32 random bytes, written as base64url: 43 characters, nothing to escape.
export const RUNBOOK_WEBHOOK_SECRET_KEY_BYTES: number = 32;
export const RUNBOOK_WEBHOOK_SECRET_KEY_LENGTH: number = 43;

const SECRET_KEY_SHAPE: RegExp = /^[A-Za-z0-9_-]{43}$/;

/*
 * Shown in place of the secret key until the reader asks to see it, as the
 * workflow webhook URL is: a page is often open on a shared screen. A fixed
 * length, so the mask says nothing about the key behind it.
 */
export const RUNBOOK_WEBHOOK_SECRET_MASK: string = "•".repeat(16);

/*
 * The body the example request sends: two values a remediation typically
 * needs, which the steps then read as $ONEUPTIME_INPUT_HOST and
 * $ONEUPTIME_INPUT_REASON (Bash) or args.inputs.host (JavaScript).
 */
export const RUNBOOK_WEBHOOK_EXAMPLE_BODY: string =
  '{"host": "web-1", "reason": "Disk almost full"}';

// The largest body a call may send: the run's inputs are kept with the run.
export const RUNBOOK_WEBHOOK_MAX_BODY_BYTES: number = 64 * 1024;

/*
 * How many runs the webhook may have going at once - queued, running, or
 * waiting for someone - before a call is refused. A leaked URL, or a tool
 * that retries in a loop, cannot keep starting runs on your Runners.
 */
export const RUNBOOK_WEBHOOK_MAX_ACTIVE_RUNS: number = 10;

/*
 * How many runs one runbook's webhook starts a minute, and how many calls
 * one address may make to runbook webhooks a minute (wrong keys included,
 * so nobody can guess a key one call at a time).
 */
export const RUNBOOK_WEBHOOK_RUNS_PER_MINUTE: number = 30;
export const RUNBOOK_WEBHOOK_CALLS_PER_ADDRESS_PER_MINUTE: number = 120;

/*
 * What a call is answered, besides the run it started. Every refusal says
 * what to do about it: the caller's delivery log or a script's output may be
 * the only place it is read. Pinned by the runbooks docs (RunbookDocsFacts)
 * and by the route's tests.
 */
export const RunbookWebhookMessages: {
  readonly notFound: string;
  readonly getNotAllowed: string;
  readonly webhookOff: string;
  readonly runbookOff: string;
  readonly noSteps: string;
  readonly tooManyActiveRuns: string;
  readonly rateLimited: string;
  readonly tooManyCallsFromAddress: string;
  readonly counterUnavailable: string;
  readonly bodyTooLarge: string;
  readonly bodyNotAnObject: string;
  readonly bodyTooDeep: string;
  readonly nulCharacter: string;
} = {
  notFound:
    "No runbook webhook answers at this URL. Copy the URL again from the runbook's Triggers page: it changes when someone resets it.",
  getNotAllowed:
    "Send a POST request to start this runbook. A GET request never starts it, so a link preview cannot run it by accident.",
  webhookOff:
    "This runbook's webhook is turned off, so the runbook was not started. Turn it on under the runbook's Triggers.",
  runbookOff:
    "This runbook is turned off, so it was not started. Turn it on with Run this runbook, under the runbook's Settings.",
  noSteps:
    "This runbook has no steps to run, so it was not started. Add steps under the runbook's Steps.",
  tooManyActiveRuns: `This runbook already has ${RUNBOOK_WEBHOOK_MAX_ACTIVE_RUNS} runs started by its webhook that are queued, running or waiting for someone, so this call did not start another. Wait for one to end, or cancel one.`,
  rateLimited: `This runbook's webhook started ${RUNBOOK_WEBHOOK_RUNS_PER_MINUTE} runs in the last minute, so this call did not start another. Try again in a minute.`,
  tooManyCallsFromAddress:
    "Too many calls to runbook webhooks from your network. Try again in a minute.",
  counterUnavailable:
    "Runbook webhooks cannot start runs right now. Try again in a minute.",
  bodyTooLarge: `The request body is larger than ${RUNBOOK_WEBHOOK_MAX_BODY_BYTES / 1024} KB, so the runbook was not started. Send only the values the runbook needs.`,
  bodyNotAnObject:
    "Send a JSON object as the request body, or no body: its top-level values become the run's inputs.",
  bodyTooDeep:
    "The request body is nested too deeply, so the runbook was not started. Send at most 32 levels of objects and lists.",
  nulCharacter:
    "A value in the request body contains a NUL character, which a step cannot receive, so the runbook was not started.",
};

// A secret key the server could have generated: 43 characters of base64url.
export function isRunbookWebhookSecretKeyShape(value: unknown): boolean {
  return typeof value === "string" && SECRET_KEY_SHAPE.test(value);
}

export type GetRunbookWebhookUrlPrefixFunction = (data: {
  runbookServiceUrl: string;
  runbookId: string;
}) => string;

// Everything before the secret key, ending in a slash.
export const getRunbookWebhookUrlPrefix: GetRunbookWebhookUrlPrefixFunction =
  (data: { runbookServiceUrl: string; runbookId: string }): string => {
    // With or without a trailing slash, the base gives the same URL.
    let base: string = data.runbookServiceUrl;

    while (base.endsWith("/")) {
      base = base.slice(0, -1);
    }

    return `${base}${RUNBOOK_WEBHOOK_PATH}/${encodeURIComponent(data.runbookId)}/`;
  };

export type GetRunbookWebhookUrlFunction = (data: {
  runbookServiceUrl: string;
  runbookId: string;
  secretKey: string;
}) => string;

export const getRunbookWebhookUrl: GetRunbookWebhookUrlFunction = (data: {
  runbookServiceUrl: string;
  runbookId: string;
  secretKey: string;
}): string => {
  return `${getRunbookWebhookUrlPrefix(data)}${encodeURIComponent(data.secretKey)}`;
};

export type GetMaskedRunbookWebhookUrlFunction = (data: {
  runbookServiceUrl: string;
  runbookId: string;
}) => string;

// The same URL with the secret key masked. Never built from the key.
export const getMaskedRunbookWebhookUrl: GetMaskedRunbookWebhookUrlFunction =
  (data: { runbookServiceUrl: string; runbookId: string }): string => {
    return `${getRunbookWebhookUrlPrefix(data)}${RUNBOOK_WEBHOOK_SECRET_MASK}`;
  };

export type GetRunbookWebhookCurlExampleFunction = (
  webhookUrl: string,
) => string;

/*
 * A request that can be pasted into a terminal as it is. One option per line,
 * so the URL stays readable on a narrow page.
 */
export const getRunbookWebhookCurlExample: GetRunbookWebhookCurlExampleFunction =
  (webhookUrl: string): string => {
    return [
      `curl -X POST "${webhookUrl}" \\`,
      `  -H "Content-Type: application/json" \\`,
      `  -d '${RUNBOOK_WEBHOOK_EXAMPLE_BODY}'`,
    ].join("\n");
  };
